    var end_mem := init_mem;

    s := ghost_begin_tx(s);
    assert s.num_entry == 0;
    assert init_mem == s.old_mem;

    var i := 0;
    while i < |writes|
        decreases |writes| - i;
        invariant 0 <= i <= |writes|;
        invariant s.mem_len == |init_mem|;
        invariant s.mem_len == |end_mem|;
        invariant 0 <= s.num_entry <= i;
        invariant |init_log| == |s.log|;
        invariant i * 2 < |s.log|;
