method query(a: array<int>, i: int, j: int) returns (res : int)
  requires 0 <= i <= j <= (a.Length) + 1
  ensures res == sum(a, i, j)
{
  res := 0;
  var ind := j-1;

  while ind >= i
    invariant i-1 <= ind < j
    invariant res == sum(a, i, j) - sum(a, i, ind+1)
    decreases ind
  {
    res := res + a[ind];
    ind := ind - 1;
  }
}

