                ==> w + nTemp.weight + |nTemp.right.Contents| == |n1.Contents| 
            decreases nTemp.Repr
        {
            w := w + nTemp.weight;
            assert w >= 0;
            if (nTemp.left != null) {
                nodesTraversed := nodesTraversed + nTemp.left.Repr + {nTemp};
            } else {
                nodesTraversed := nodesTraversed + {nTemp};
            }
            nTemp := nTemp.right;
