        p :=0;
        assert p == Count(CountIndex,a);
    } else{
        assert |a| == b.Length && 0<=CountIndex-1 <=|a|;
        assert (a[CountIndex-1]%2 ==0 ==>|a| == b.Length && 0<= CountIndex -1 <|a| && 1+ Count(CountIndex-1,a) == Count(CountIndex,a)) && 
