        modifies log_;
        modifies this;
        requires state_inv();
        requires ghost_state_equiv(gs);
        requires ghost_state_inv(gs);
        requires log_[0] == 0;
        ensures mem_ == old(mem_);
        ensures log_ == old(log_);
        ensures state_inv();
        ensures ghost_state_equiv(gs);
        ensures ghost_tx_inv(gs);
