        gs := ghost_begin_tx(gs);
        assert state_inv();
    }

    method commit_tx()
        modifies log_;
        modifies this;
        requires state_inv();
        requires ghost_state_equiv(gs);
        requires ghost_state_inv(gs);
        requires ghost_tx_inv(gs);
        requires old_mem_equiv(gs);
        ensures mem_ == old(mem_);
        ensures log_ == old(log_);
        ensures ghost_state_equiv(gs);
        ensures state_inv();
