datatype List<T> = Nil | Cons(head: T, tail: List<T>)

function add(l : List<int>) : int {
  match l
  case Nil => 0
  case Cons(x,xs) => x + add(xs)
}

method addImp(l : List<int>) returns (r: int)
  ensures r == add(l)
{
  r := 0;
  var ll := l;
  while (ll != Nil)
    decreases ll
    invariant r==add(l) - add(ll)
  {
    r := r + ll.head;
    ll := ll.tail;

  }

  assert r == add(l);
}

