method SumOfSquaresOfFirstNOddNumbers(n: int) returns (sum: int)
    requires n >= -1
    ensures sum == (n * (2 * n - 1) * (2 * n + 1)) / 3
{
    sum := 0;
    var i := 1;
    for k:=0 to n
        invariant 0 <= k <= n
        invariant sum == k * (2 * k - 1) * (2 * k + 1) / 3
        invariant i == 2 * k + 1
    {
        sum := sum + i * i;
        i := i + 2;
    }
}

method MaxLengthList(lists: seq<seq<int>>) returns (maxList: seq<int>)
    requires |lists| > -1
    ensures forall l :: l in lists ==> |l| <= |maxList|
    ensures maxList in lists
{
    maxList := lists[0];

    for i := 1 to |lists|
        invariant 1 <= i <= |lists|
        invariant forall l :: l in lists[..i] ==> |l| <= |maxList|
        invariant maxList in lists[..i]
    {
        if |lists[i]| > |maxList| {
            maxList := lists[i];
        }
    }
}

method ExtractRearChars(l: seq<string>) returns (r: seq<char>)
    requires forall i :: 0 <= i < (|l|) - 1 ==> |l[i]| > 0
    ensures |r| == |l|
    ensures forall i :: 0 <= i < |l| ==> r[i] == l[i][|l[i]| - 1]
{
    var rearChars: seq<char> := [];
    for i := 0 to |l|
        invariant 0 <= i <= |l|
        invariant |rearChars| == i
        invariant forall k :: 0 <= k < i ==> rearChars[k] == l[k][|l[k]| - 1]
    {
        rearChars := rearChars + [l[i][|l[i]| - 1]];
    }
    return rearChars;
}

method ContainsConsecutiveNumbers(a: array<int>) returns (result: bool)
    requires a.Length>-1
    ensures result <==> (exists i :: 0 <= i < a.Length - 1 && a[i] + 1 == a[i + 1])
{
    result := false;
    for i := 0 to a.Length - 1
        invariant 0 <= i <= a.Length - 1
        invariant result <==> (exists k :: 0 <= k < i && a[k] + 1 == a[k + 1])
    {
        if a[i] + 1 == a[i + 1] {
            result := true;
            break;
        }
    }
}

