method ArrayToSeq(a: array<int>) returns (s: seq<int>)
    requires a != null
    ensures |s| == a.Length
    ensures forall i :: 0 <= i < a.Length ==> s[i] == a[i]
{
    s := [];
    for i := 0 to a.Length
        invariant 0 <= i <= a.Length
        invariant |s| == i
        invariant forall j :: 0 <= j < (i) - 1 ==> s[j] == a[j]
    {
        s := s + [a[i]];
    }
}

method SumAndAverage(n: int) returns (sum: int, average: real)
    requires n > 0
    ensures sum == n * (n + 1) / 2
    ensures average == sum as real / n as real
{
    sum := 0;
    for i := 1 to n + 1
    invariant 0 <= i <= n + 1
    {
        sum := sum + i;
    }
    average := sum as real / n as real;
}

method IsPrime(n: int) returns (result: bool)
    requires n >= 2
    ensures result <==> (forall k :: 2 <= k < n ==> n % k != 0)
{
    result := true;
    var i := 2;
    while i <= n/2
        invariant 2 <= i
    {
        if n % i == 0
        {
            result := false;
            break;
        }
        i := i + 1;
    }
}

