  i := 0;
  while (i < n)
  invariant 0 <= i <= n <= a.Length;
  invariant 0 <= mi < n;
  invariant forall k :: 0 <= k < i ==> a[mi] >= a[k];
  decreases n-i;
  {
    if (a[i] > a[mi])
    { 
      mi := i; 
    }
    i := i + 1;
  }
  return mi;
}

