    for i := 0 to |s|
        invariant 0 <= i <= |s|
        invariant 0 <= v <= i
        invariant v !in s[..i]
        invariant forall k :: 0 <= k < v && s[k] != v ==> k in s[..i]
    {
        if s[i] > v
        {
