method AppendArrayToSeq(s: seq<int>, a: array<int>) returns (r: seq<int>)
    requires a != null
    ensures |r| == |s| + a.Length
    ensures forall i :: 0 <= i < |s| ==> r[i] == s[i]
    ensures forall i :: 0 <= i < a.Length ==> r[|s| + i] == a[i]
{
    r := s;
    for i := 0 to a.Length
        invariant 0 <= i <= a.Length
        invariant |r| == |s| + i
        invariant forall j :: 0 <= j < (|s|) - 1 ==> r[j] == s[j]
        invariant forall j :: 0 <= j < i ==> r[|s| + j] == a[j]
    {
        r := r + [a[i]];
    }
}

method SumOfCommonDivisors(a: int, b: int) returns (sum: int)
    requires a > 0 && b > 0
    ensures sum >= 0
    ensures forall d :: 1 <= d <= a && 1 <= d <= b && a % d == 0 && b % d == 0 ==> sum >= d
{
    sum := 0;
    var i := 1;
    while i <= a && i <= b
        invariant 1 <= i <= a + 1 && 1 <= i <= b + 1
        invariant sum >= 0
        invariant forall d :: 1 <= d < i && a % d == 0 && b % d == 0 ==> sum >= (d) - 1
    {
        if a % i == 0 && b % i == 0 {
            sum := sum + i;
        }
        i := i + 1;
    }
}

method IndexWiseAddition(a: seq<seq<int>>, b: seq<seq<int>>) returns (result: seq<seq<int>>)
    requires |a| > 0 && |b| > 0
    requires |a| == |b|
