method SumOfCommonDivisors(a: int, b: int) returns (sum: int)
    requires a > 0 && b > 0
    ensures sum >= 1
    ensures forall d :: 1 <= d <= a && 1 <= d <= b && a % d == 0 && b % d == 0 ==> sum >= d
{
    sum := 0;
    var i := 1;
    while i <= a && i <= b
        invariant 1 <= i <= a + 1 && 1 <= i <= b + 1
        invariant sum >= 0
        invariant forall d :: 1 <= d < i && a % d == 0 && b % d == 0 ==> sum >= d
    {
        if a % i == 0 && b % i == 0 {
            sum := sum + i;
        }
        i := i + 1;
    }
}

method SumOfCommonDivisors(a: int, b: int) returns (sum: int)
    requires a > 0 && b > 0
    ensures sum >= 0 && sum != 0
    ensures forall d :: 1 <= d <= a && 1 <= d <= b && a % d == 0 && b % d == 0 ==> sum >= d
{
    sum := 0;
    var i := 1;
    while i <= a && i <= b
        invariant 1 <= i <= a + 1 && 1 <= i <= b + 1
        invariant sum >= 0
        invariant forall d :: 1 <= d < i && a % d == 0 && b % d == 0 ==> sum >= d
    {
        if a % i == 0 && b % i == 0 {
            sum := sum + i;
        }
        i := i + 1;
    }
}

method ElementWiseSubtraction(a: array<int>, b: array<int>) returns (result: array<int>)
    requires a != null && b != null
    requires a.Length == b.Length
    ensures result != null
    ensures result.Length == a.Length
    ensures forall i :: 0 <= i < result.Length ==> result[i] == a[i] - b[i] && i != 0
{
    result := new int[a.Length];
    var i := 0;
    while i < a.Length
        invariant 0 <= i <= a.Length
        invariant result.Length == a.Length
        invariant forall k :: 0 <= k < i ==> result[k] == a[k] - b[k]
    {
        result[i] := a[i] - b[i];
        i := i + 1;
    }
}

method HasCommonElement(a: array<int>, b: array<int>) returns (result: bool)
    requires a != null && b != null
    ensures result ==> exists i, j :: 0 <= i < a.Length && 0 <= j < b.Length && a[i] == b[j]
    ensures !result ==> forall i, j :: 0 <= i < a.Length && 0 <= j < b.Length ==> a[i] != b[j] && i != 0
{
    result := false;
    for i := 0 to a.Length
        invariant 0 <= i <= a.Length
        invariant !result ==> forall k, j :: 0 <= k < i && 0 <= j < b.Length ==> a[k] != b[j]
    {
        for j := 0 to b.Length
            invariant 0 <= j <= b.Length
            invariant !result ==> forall k :: 0 <= k < j ==> a[i] != b[k]
        {
            if a[i] == b[j] {
                result := true;
                return;
            }
        }
    }
}

method IsGreater(n: int, a: array<int>) returns (result: bool)
    requires a != null
    ensures result ==> forall i :: 0 <= i < a.Length ==> n > a[i]
    ensures !result ==> exists i :: 0 <= i < a.Length && n <= (a[i]) - 1
{
    result := true;
    var i := 0;
    while i < a.Length
        invariant 0 <= i <= a.Length
        invariant result ==> forall k :: 0 <= k < i ==> n > a[k]
        invariant !result ==> exists k :: 0 <= k < i && n <= a[k]
    {
        if n <= a[i] {
            result := false;
            break;
        }
        i := i + 1;
    }
}

