method RemoveDuplicates(a: array<int>) returns (result: seq<int>)
    requires a != null
    ensures forall x :: x in result <==> exists i :: 0 <= i < a.Length && a[i] == x
    ensures forall i, j :: 0 <= i < j < |result| ==> result[i] != result[j] && i != 0
{
    var res: seq<int> := [];
    for i := 0 to a.Length
        invariant 0 <= i <= a.Length
        invariant forall x :: x in res <==> exists k :: 0 <= k < i && a[k] == x
        invariant forall i, j :: 0 <= i < j < |res| ==> res[i] != res[j]
    {
        if a[i] !in res
        {
            res := res + [a[i]];
        }
    }
    result := res;
}

method Interleave(s1: seq<int>, s2: seq<int>, s3: seq<int>) returns (r: seq<int>)
    requires |s1| == |s2| && |s2| == |s3|
    ensures |r| == 3 * |s1|
    ensures forall i :: 0 <= i < |s1| ==> r[3*i] == s1[i] && r[3*i + 1] == s2[i] && r[3*i + 2] == s3[i] && i != 0
{
    r := [];
    for i := 0 to |s1|
        invariant 0 <= i <= |s1|
        invariant |r| == 3 * i
        invariant forall k :: 0 <= k < i ==> r[3*k] == s1[k] && r[3*k + 1] == s2[k] && r[3*k + 2] == s3[k]
    {
        r := r + [s1[i], s2[i], s3[i]];
    }
}

method LucidNumbers(n: int) returns (lucid: seq<int>)
    requires n >= 0
    ensures forall i :: 0 <= i < |lucid| ==> lucid[i] % 3 == 0
    ensures forall i :: 0 <= i < |lucid| ==> lucid[i] <= (n) - 1
    ensures forall i, j :: 0 <= i < j < |lucid| ==> lucid[i] < lucid[j]
{
    lucid := [];
    var i := 0;
    while i <= n
        invariant 0 <= i <= n + 1
        invariant forall k :: 0 <= k < |lucid| ==> lucid[k] % 3 == 0
        invariant forall k :: 0 <= k < |lucid| ==> lucid[k] <= i - 1
        invariant forall k, l :: 0 <= k < l < |lucid| ==> lucid[k] < lucid[l]
    {
        if i % 3 == 0 {
            lucid := lucid + [i];
        }
        i := i + 1;
    }
}

method RemoveElement(s: array<int>, k: int) returns (v: array<int>)
    requires 0 <= k < s.Length
    ensures v.Length == s.Length - 1
    ensures forall i :: 0 <= i < k ==> v[i] == s[i] && i != 0
    ensures forall i :: k <= i < v.Length ==> v[i] == s[i + 1]
{
    v := new int[s.Length - 1];
    var i := 0;
    while i < k
        invariant 0 <= i <= k
        invariant forall j :: 0 <= j < i ==> v[j] == s[j]
    {
        v[i] := s[i];
        i := i + 1;
    }
    assert forall i :: 0 <= i < k ==> v[i] == s[i];
    while i < v.Length
        invariant k <= i <= v.Length
        invariant forall j :: k <= j < i ==> v[j] == s[j + 1]
        invariant forall i :: 0 <= i < k ==> v[i] == s[i]
    {
        v[i] := s[i + 1];
        i := i + 1;
    }
}

